-- Custom emote pack for TwitchEmotes (v2).
-- emotes.lua is generated by build.py; this file is the same for every pack.
-- Everything here is local: the only globals touched are the base addon's own
-- tables, plus one wrapper around its animator.

local ADDON, ns = ...
local PATH = "Interface\\AddOns\\" .. ADDON .. "\\emotes\\"
local SIZE = ":28:28" -- chat display size, same as the base addon and Hardcore
local MENU_MAX = 40   -- base dropdown menus hold about 45 entries

if type(TwitchEmotes) ~= "table" or type(TwitchEmotes.AddEmote) ~= "function" then
    print("|cffff5555" .. ADDON .. ":|r TwitchEmotes is not loaded, pack disabled.")
    return
end

local emotes = ns.emotes or {}
local anim = ns.anim or {}
local names = {}

-- 1. Register every emote: typed word -> texture.
for _, e in ipairs(emotes) do
    local name, file = e[1], e[2]
    local tex = PATH .. file
    if anim[file] and type(TwitchEmotes_animation_metadata) == "table" then
        -- Animated: bare path, like the base addon's own animated emotes, so
        -- its autocomplete finds the frame data (it looks it up by this value).
        TwitchEmotes_animation_metadata[tex] = anim[file]
        TwitchEmotes:AddEmote(name, name, tex)
    else
        -- e[3]: wide emotes carry their own size and texture coordinates.
        TwitchEmotes:AddEmote(name, name, tex .. (e[3] or SIZE))
    end
    names[#names + 1] = name
end

-- 2. Autocomplete. The base addon built AllTwitchEmoteNames at its own
-- ADDON_LOADED (before this pack loaded) and every chat edit box holds a
-- reference to that same table, so adding to it is enough. Calling
-- SetupAutoComplete again (as Hardcore does) would stack a second set of hooks.
-- If autocomplete is off now, turning it on later rebuilds the list from
-- TwitchEmotes_defaultpack, which already has these emotes.
if type(AllTwitchEmoteNames) == "table" and #AllTwitchEmoteNames > 0 then
    local seen = {}
    for _, n in ipairs(AllTwitchEmoteNames) do seen[n] = true end
    for _, n in ipairs(names) do
        if not seen[n] then AllTwitchEmoteNames[#AllTwitchEmoteNames + 1] = n end
    end
    table.sort(AllTwitchEmoteNames)
end

-- 3. Emote picker (minimap button menu): one category, split if it is long.
if type(TwitchEmotes.AddCategory) == "function" and #names > 0 then
    local sorted = {}
    for i, n in ipairs(names) do sorted[i] = n end
    table.sort(sorted, function(a, b) return a:lower() < b:lower() end)
    local title = ns.title or ADDON
    local parts = math.ceil(#sorted / MENU_MAX)
    for p = 1, parts do
        local chunk = {}
        for i = (p - 1) * MENU_MAX + 1, math.min(p * MENU_MAX, #sorted) do
            chunk[#chunk + 1] = sorted[i]
        end
        local label = parts > 1 and (title .. " " .. p) or title
        pcall(TwitchEmotes.AddCategory, TwitchEmotes, label, chunk)
    end
end

-- 4. Animation. The base animator only matches textures under
-- Interface\AddOns\TwitchEmotes\Emotes\, so emotes in this folder would sit
-- on frame 1. Wrap it (Hardcore replaces it outright) and animate this pack's
-- paths after the original runs.
local issecret = type(issecretvalue) == "function" and issecretvalue or nil

local function animateOurs(fontstring, w, h)
    local ok, txt = pcall(fontstring.GetText, fontstring)
    if not ok or type(txt) ~= "string" then return end
    if issecret then
        local sok, secret = pcall(issecret, txt)
        if not sok or secret then return end
    end
    local needle = "|T" .. PATH
    if not txt:find(needle, 1, true) then return end

    local out, pos, changed = {}, 1, false
    while true do
        local s = txt:find(needle, pos, true)
        if not s then break end
        local e = txt:find("|t", s + 2, true)
        if not e then break end
        local tga = txt:sub(s + 2, e - 1):match("^(.-%.tga)")
        local a = tga and TwitchEmotes_animation_metadata[tga]
        out[#out + 1] = txt:sub(pos, s - 1)
        if a then
            local frame = TwitchEmotes_GetCurrentFrameNum(a)
            if w and h then
                out[#out + 1] = TwitchEmotes_BuildEmoteFrameStringWithDimensions(tga, a, frame, w, h)
            else
                out[#out + 1] = TwitchEmotes_BuildEmoteFrameString(tga, a, frame)
            end
            changed = true
        else
            out[#out + 1] = txt:sub(s, e + 1)
        end
        pos = e + 2
    end
    if not changed then return end
    out[#out + 1] = txt:sub(pos)

    local nTxt = table.concat(out)
    if fontstring.messageInfo ~= nil then
        fontstring.messageInfo.message = nTxt
    end
    fontstring:SetText(nTxt)
end

local original = TwitchEmotesAnimator_UpdateEmoteInFontString
if type(original) == "function"
    and type(TwitchEmotes_GetCurrentFrameNum) == "function"
    and type(TwitchEmotes_BuildEmoteFrameString) == "function"
    and type(TwitchEmotes_BuildEmoteFrameStringWithDimensions) == "function" then
    TwitchEmotesAnimator_UpdateEmoteInFontString = function(fontstring, w, h)
        original(fontstring, w, h)
        if fontstring then animateOurs(fontstring, w, h) end
    end
end

-- 5. Chat addons that draw their own messages. EllesmereUI Chat keeps
-- Blizzard's chat frames running but invisible (alpha 0) and shows every line
-- in its own unnamed ScrollingMessageFrame on the chat panel (CFD(cf).bg).
-- The base animator walks only Blizzard's visibleLines, so with it every
-- animated emote (ours and the base pack's) sits on frame 1. Walk those
-- frames too, with the same per-line updater. Read-only on EllesmereUI's
-- side: its exported side-table accessor, then GetChildren on its panel.
local function chatAddonFrames()
    local list = {}
    local EUI = _G.EllesmereUI
    local CFD = type(EUI) == "table" and EUI._chatCFD
    if type(CFD) ~= "function" or type(CHAT_FRAMES) ~= "table" then return list end
    for _, name in pairs(CHAT_FRAMES) do
        local cf = _G[name]
        local ok, d = pcall(CFD, cf)
        local bg = cf and ok and type(d) == "table" and d.bg
        if bg and bg.GetChildren then
            for _, child in ipairs({ bg:GetChildren() }) do
                -- No object-type test: on Forever its message frame reports
                -- "Frame" (a mixin frame), not "ScrollingMessageFrame".
                if child ~= cf and child.GetName and not child:GetName()
                    and type(child.visibleLines) == "table" then
                    list[#list + 1] = child
                end
            end
        end
    end
    return list
end

local ticker = CreateFrame("Frame")
local since, rescan, frames = 0, 10, {}
local lastErr, ticks = nil, 0
ticker:SetScript("OnUpdate", function(_, elapsed)
    since, rescan = since + elapsed, rescan + elapsed
    if since < 0.033 then return end
    since = 0
    if not (Emoticons_Settings and Emoticons_Settings.ENABLE_ANIMATEDEMOTES) then return end
    if rescan >= 2 then rescan = 0; frames = chatAddonFrames() end
    ticks = ticks + 1
    local update = TwitchEmotesAnimator_UpdateEmoteInFontString
    -- No visibility test: in game these frames report IsVisible() false
    -- even while on screen. Lines are cheap to skip (no texture, no work).
    for _, smf in ipairs(frames) do
        for _, line in ipairs(smf.visibleLines) do
            if line.messageInfo ~= TwitchEmotes_HoverMessageInfo then
                local ok, err = pcall(update, line, 28, 28)
                if not ok then lastErr = err end
            end
        end
    end
end)

-- /tam debug: what the chat-addon hook sees (for bug reports).
local function debugReport()
    local p = function(...) print("|cff66ccff[tam]|r", ...) end
    local esc = function(s) return (tostring(s):gsub("|", "||")) end
    local EUI = _G.EllesmereUI
    p("animation setting:", tostring(Emoticons_Settings and Emoticons_Settings.ENABLE_ANIMATEDEMOTES),
      "| base update frame:", tostring(TwitchEmotesUpdateFrame ~= nil),
      "| wrapper on:", tostring(TwitchEmotesAnimator_UpdateEmoteInFontString ~= original))
    p("EllesmereUI:", tostring(type(EUI) == "table"), "| _chatCFD:", tostring(type(EUI) == "table" and type(EUI._chatCFD)),
      "| CHAT_FRAMES:", tostring(type(CHAT_FRAMES) == "table" and #CHAT_FRAMES))
    if type(EUI) == "table" and type(EUI._chatCFD) == "function" and ChatFrame1 then
        local ok, d = pcall(EUI._chatCFD, ChatFrame1)
        local bg = ok and type(d) == "table" and d.bg
        p("ChatFrame1 panel:", tostring(bg ~= nil and bg ~= false))
        if bg and bg.GetChildren then
            for i, c in ipairs({ bg:GetChildren() }) do
                p("  child", i, c.GetObjectType and c:GetObjectType() or "?", "name:", tostring(c.GetName and c:GetName()),
                  "visibleLines:", tostring(type(c.visibleLines) == "table" and #c.visibleLines),
                  "visible:", tostring(c.IsVisible and c:IsVisible()), "shown:", tostring(c.IsShown and c:IsShown()),
                  "alpha:", tostring(c.GetEffectiveAlpha and c:GetEffectiveAlpha()))
            end
        end
    end
    local found = chatAddonFrames()
    p("frames hooked:", #found, "| ticks:", ticks, "| last error:", esc(lastErr))
    for i, smf in ipairs(found) do
        local n, shown = 0, 0
        for _, line in ipairs(smf.visibleLines or {}) do
            n = n + 1
            local ok, t = pcall(line.GetText, line)
            local secret = ok and type(issecretvalue) == "function" and issecretvalue(t)
            if ok and not secret and type(t) == "string" and t:find("|T", 1, true) and shown < 2 then
                shown = shown + 1
                local tex = t:match("|T(.-)|t")
                p("  frame", i, "emote line, messageInfo:", tostring(line.messageInfo ~= nil), "tex:", esc(tex))
                local path = tex and tex:match("^(.-%.tga)")
                p("    anim data for path:", tostring(path and TwitchEmotes_animation_metadata[path] ~= nil))
                local before = t
                local uok, uerr = pcall(TwitchEmotesAnimator_UpdateEmoteInFontString, line, 28, 28)
                local _, after = pcall(line.GetText, line)
                p("    update ok:", tostring(uok), esc(uerr), "| text changed:", tostring(after ~= before))
            elseif secret and shown < 2 then
                shown = shown + 1
                p("  frame", i, "line text is SECRET (chat lockdown)")
            end
        end
        p("  frame", i, "lines:", n)
    end
end

-- /<pack> lists the pack's emotes in chat.
local slash = ADDON:upper():gsub("[^%w]", "")
_G["SLASH_" .. slash .. "1"] = "/" .. ADDON:lower():gsub("^twitchemotes_", "te")
if ns.slash then _G["SLASH_" .. slash .. "2"] = "/" .. ns.slash:gsub("^/", "") end
SlashCmdList[slash] = function(msg)
    if msg and msg:lower():match("^%s*debug") then return debugReport() end
    local line, n = "", 0
    for _, e in ipairs(emotes) do
        local tex, a = PATH .. e[2], anim[e[2]]
        local icon = a and TwitchEmotes_BuildEmoteFrameStringWithDimensions(tex, a, 0, 20, 20)
            or ("|T" .. tex .. (e[3] or SIZE):gsub("^:28:(%d+)", function(w)
                return ":20:" .. math.floor(w * 20 / 28 + 0.5) end) .. "|t")
        line = line .. icon .. " " .. e[1] .. "  "
        n = n + 1
        if n == 6 then print(line); line, n = "", 0 end
    end
    if n > 0 then print(line) end
    print(ADDON .. ": " .. #emotes .. " emotes. Type the name in chat, or :name for autocomplete.")
end
